window.docContents[105].resolve({"/#PropertyKindCalculus-Blueprint--Requirements--Out-of-scope-_LPAR_for-now_RPAR_":{"contents":"Value representation in the structural sense — scalar / vector / tensor order,\ncoordinate frames, bound-versus-free vectors, and frame transformations — is not\nyet specified here (this is the structural representation axis, distinct from\nR10's numeric carrier ). It is a genuine systems-engineering requirement, but\na separate, orthogonal axis: its principled home is an index over the kind,\nnever a layer the kind hangs beneath (the inversion the Why a calculus, not a\ntaxonomy section charges against SysML v2). Stating it as owed keeps the boundary\nhonest.\n\n","context":"PropertyKindCalculus Blueprint\u0009Requirements","header":"1.6. Out of scope (for now)","id":"/#PropertyKindCalculus-Blueprint--Requirements--Out-of-scope-_LPAR_for-now_RPAR_"}});